#!/usr/bin/env bash
# Generate the Claude Code layout from the IBM Bob sources (.bob is the single source of truth).
#   .bob/skills/<name>/      -> .claude/skills/<name>/     (identical SKILL.md format, copied)
#   .bob/rules/*.md          -> CLAUDE.md                  (imports each rule with @path)
# Usage: sync_platforms.sh [--check]
#   --check  exit 1 if the generated files are out of date (CI-friendly), change nothing
set -euo pipefail
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT"
CHECK=0; [ "${1:-}" = "--check" ] && CHECK=1

render_claude_md() {
  echo "# CLAUDE.md"
  echo
  echo "<!-- GENERATED by scripts/sync_platforms.sh from .bob/rules - edit the rules, not this file. -->"
  echo "Project rules (shared with IBM Bob). Skills are in .claude/skills/ and are invoked by name."
  echo
  # AGENTS.md first (index), then the remaining rules alphabetically.
  echo "@.bob/rules/AGENTS.md"
  for f in $(ls .bob/rules/*.md | LC_ALL=C sort); do
    [ "$(basename "$f")" = "AGENTS.md" ] && continue
    echo "@$f"
  done
}

TMP="$(mktemp)"; trap 'rm -f "$TMP"' EXIT
render_claude_md > "$TMP"

if [ "$CHECK" -eq 1 ]; then
  RC=0
  cmp -s "$TMP" CLAUDE.md || { echo "OUT OF DATE: CLAUDE.md"; RC=1; }
  if [ -d .claude/skills ]; then
    diff -rq .bob/skills .claude/skills >/dev/null || { echo "OUT OF DATE: .claude/skills"; RC=1; }
  else echo "MISSING: .claude/skills"; RC=1; fi
  [ "$RC" -eq 0 ] && echo "OK: Claude Code layout is in sync"
  exit "$RC"
fi

cp "$TMP" CLAUDE.md
rm -rf .claude/skills
mkdir -p .claude/skills
cp -R .bob/skills/. .claude/skills/
echo "generated: CLAUDE.md"
echo "generated: .claude/skills ($(ls .claude/skills | wc -l | tr -d ' ') skills)"
